/// <summary>
/// Runs the production update startup process.
/// </summary>
public void run()
{
    next run();

    AVARUMProdRobotExport prodRobotExport=new AVARUMProdRobotExport();
    prodRobotExport.doExport(prodTable);

    /// Send email notification for production start
    prodTable.sendMail_AVA();
}
